import { useState } from "react";
import "./styles.css";

type ToggleProps = {
  checked: boolean;
  onChange: () => void;
  label: string;
  description: string;
};

function Toggle({ checked, onChange, label, description }: ToggleProps) {
  return (
    <label className="setting-row">
      <span>
        <span className="setting-label">{label}</span>
        <span className="setting-description">{description}</span>
      </span>
      <input
        aria-label={label}
        checked={checked}
        className="toggle-input"
        onChange={onChange}
        type="checkbox"
      />
      <span aria-hidden="true" className="toggle-track"><span /></span>
    </label>
  );
}

export default function App() {
  const [theme, setTheme] = useState("system");
  const [spellcheck, setSpellcheck] = useState(true);
  const [lineNumbers, setLineNumbers] = useState(false);
  const [compact, setCompact] = useState(false);
  const [saved, setSaved] = useState(false);

  const save = () => {
    setSaved(true);
    window.setTimeout(() => setSaved(false), 1600);
  };

  return (
    <main className="app-shell">
      <section className="settings-card" aria-labelledby="settings-title">
        <aside className="sidebar">
          <div className="brand"><span className="brand-mark">N</span><span>Notionary</span></div>
          <nav aria-label="Settings sections">
            <a className="nav-item active" href="#general"><span>⌘</span> General</a>
            <a className="nav-item" href="#editor"><span>✎</span> Editor</a>
            <a className="nav-item" href="#appearance"><span>◐</span> Appearance</a>
            <a className="nav-item" href="#account"><span>◉</span> Account</a>
          </nav>
          <button className="help-link" type="button">?&nbsp;&nbsp; Help center</button>
        </aside>

        <div className="content">
          <header className="page-header">
            <div><p className="eyebrow">Preferences</p><h1 id="settings-title">General settings</h1></div>
            <button className="close-button" aria-label="Close settings" type="button">×</button>
          </header>

          <div className="settings-content">
            <section id="general" className="settings-section">
              <h2>Workspace</h2>
              <label className="field-label" htmlFor="workspace-name">Workspace name</label>
              <div className="input-wrap"><span aria-hidden="true">⌂</span><input defaultValue="My notes" id="workspace-name" /></div>
              <p className="hint">This name is visible only to you.</p>
            </section>

            <section id="appearance" className="settings-section bordered">
              <h2>Appearance</h2>
              <div className="theme-options" role="radiogroup" aria-label="Color theme">
                {[["light", "☼", "Light"], ["system", "◐", "System"], ["dark", "☾", "Dark"]].map(([value, icon, label]) => (
                  <button key={value} className={`theme-option ${theme === value ? "selected" : ""}`} onClick={() => setTheme(value)} role="radio" aria-checked={theme === value} type="button">
                    <span>{icon}</span>{label}
                  </button>
                ))}
              </div>
            </section>

            <section id="editor" className="settings-section bordered">
              <h2>Writing</h2>
              <Toggle checked={spellcheck} onChange={() => setSpellcheck(!spellcheck)} label="Spell check" description="Highlight possible spelling mistakes as you write." />
              <Toggle checked={lineNumbers} onChange={() => setLineNumbers(!lineNumbers)} label="Line numbers" description="Show line numbers in the editor." />
              <Toggle checked={compact} onChange={() => setCompact(!compact)} label="Compact note list" description="Fit more notes into the sidebar." />
            </section>
          </div>

          <footer className="footer-actions">
            <span className="saved-state" aria-live="polite">{saved ? "Changes saved" : ""}</span>
            <button className="secondary-button" type="button">Cancel</button>
            <button className="primary-button" onClick={save} type="button">Save changes</button>
          </footer>
        </div>
      </section>
    </main>
  );
}

