import { useState } from 'react';
import './styles.css';

type ToggleProps = {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label: string;
  description: string;
};

function Toggle({ checked, onChange, label, description }: ToggleProps) {
  return (
    <div className="setting-row">
      <div>
        <p className="setting-label">{label}</p>
        <p className="setting-description">{description}</p>
      </div>
      <button
        aria-label={label}
        aria-pressed={checked}
        className={`toggle ${checked ? 'is-on' : ''}`}
        onClick={() => onChange(!checked)}
        type="button"
      >
        <span />
      </button>
    </div>
  );
}

export default function App() {
  const [appearance, setAppearance] = useState('System');
  const [font, setFont] = useState('Inter');
  const [compactMode, setCompactMode] = useState(false);
  const [spellcheck, setSpellcheck] = useState(true);
  const [autoSave, setAutoSave] = useState(true);
  const [saved, setSaved] = useState(false);

  function saveSettings() {
    setSaved(true);
    window.setTimeout(() => setSaved(false), 1800);
  }

  return (
    <main className="app-shell">
      <section className="settings-card" aria-labelledby="settings-title">
        <header className="card-header">
          <div className="title-mark" aria-hidden="true">N</div>
          <div>
            <p className="eyebrow">Workspace</p>
            <h1 id="settings-title">Settings</h1>
          </div>
          <button className="close-button" aria-label="Close settings" type="button">×</button>
        </header>

        <div className="settings-body">
          <nav className="settings-nav" aria-label="Settings sections">
            <button className="nav-item active" type="button"><span>⌘</span> General</button>
            <button className="nav-item" type="button"><span>⌕</span> Editor</button>
            <button className="nav-item" type="button"><span>♧</span> Appearance</button>
            <button className="nav-item" type="button"><span>♙</span> Account</button>
          </nav>

          <div className="settings-content">
            <section>
              <div className="section-heading">
                <h2>General</h2>
                <p>Set up how your notes work for you.</p>
              </div>

              <div className="control-grid">
                <label className="select-field">
                  <span>Appearance</span>
                  <select value={appearance} onChange={(event) => setAppearance(event.target.value)}>
                    <option>System</option>
                    <option>Light</option>
                    <option>Dark</option>
                  </select>
                </label>
                <label className="select-field">
                  <span>Editor font</span>
                  <select value={font} onChange={(event) => setFont(event.target.value)}>
                    <option>Inter</option>
                    <option>Source Serif</option>
                    <option>Mono</option>
                  </select>
                </label>
              </div>

              <div className="setting-list">
                <Toggle checked={compactMode} onChange={setCompactMode} label="Compact layout" description="Fit more notes into your sidebar." />
                <Toggle checked={spellcheck} onChange={setSpellcheck} label="Spell check" description="Underline possible spelling mistakes as you write." />
                <Toggle checked={autoSave} onChange={setAutoSave} label="Save automatically" description="Keep changes safe while you work." />
              </div>
            </section>

            <section className="danger-zone" aria-labelledby="storage-title">
              <div>
                <h2 id="storage-title">Storage</h2>
                <p>Export a copy of all your notes at any time.</p>
              </div>
              <button className="secondary-button" type="button">Export notes</button>
            </section>
          </div>
        </div>

        <footer className="card-footer">
          <span className={saved ? 'save-status visible' : 'save-status'}>Changes saved</span>
          <div className="footer-actions">
            <button className="text-button" type="button">Cancel</button>
            <button className="primary-button" onClick={saveSettings} type="button">Save changes</button>
          </div>
        </footer>
      </section>
    </main>
  );
}

