import { useState } from "react";

type ToggleProps = {
  enabled: boolean;
  onChange: () => void;
};

function Toggle({ enabled, onChange }: ToggleProps) {
  return (
    <button
      className={`toggle ${enabled ? "is-on" : ""}`}
      type="button"
      aria-pressed={enabled}
      onClick={onChange}
    >
      <span />
    </button>
  );
}

export default function App() {
  const [activeSection, setActiveSection] = useState("Appearance");
  const [theme, setTheme] = useState("System");
  const [compactMode, setCompactMode] = useState(false);
  const [spellcheck, setSpellcheck] = useState(true);
  const [dailyNote, setDailyNote] = useState(true);

  const sections = ["General", "Appearance", "Editor", "Notes", "Account"];

  return (
    <main className="app-shell">
      <section className="settings-card" aria-label="Settings">
        <aside className="sidebar">
          <div className="brand">
            <div className="brand-mark">N</div>
            <span>noted</span>
          </div>

          <nav aria-label="Settings sections">
            <p className="nav-label">SETTINGS</p>
            {sections.map((section) => (
              <button
                className={`nav-item ${activeSection === section ? "active" : ""}`}
                key={section}
                type="button"
                onClick={() => setActiveSection(section)}
              >
                <span className="nav-icon" aria-hidden="true">
                  {section === "Appearance" ? "◐" : section === "Account" ? "◎" : "○"}
                </span>
                {section}
              </button>
            ))}
          </nav>

          <button className="help-link" type="button">? Help & feedback</button>
        </aside>

        <div className="content">
          <header>
            <p className="eyebrow">PREFERENCES</p>
            <h1>{activeSection}</h1>
            <p className="subtitle">Personalize how Noted looks and feels.</p>
          </header>

          <div className="settings-list">
            <div className="setting-row theme-row">
              <div>
                <h2>Theme</h2>
                <p>Choose the color mode for your workspace.</p>
              </div>
              <div className="segmented-control" aria-label="Theme">
                {["Light", "System", "Dark"].map((option) => (
                  <button
                    className={theme === option ? "selected" : ""}
                    key={option}
                    type="button"
                    onClick={() => setTheme(option)}
                  >
                    {option}
                  </button>
                ))}
              </div>
            </div>

            <div className="setting-row">
              <div>
                <h2>Compact layout</h2>
                <p>Reduce spacing between notes and controls.</p>
              </div>
              <Toggle enabled={compactMode} onChange={() => setCompactMode(!compactMode)} />
            </div>

            <div className="setting-row">
              <div>
                <h2>Spell check</h2>
                <p>Highlight potential spelling mistakes as you write.</p>
              </div>
              <Toggle enabled={spellcheck} onChange={() => setSpellcheck(!spellcheck)} />
            </div>

            <div className="setting-row">
              <div>
                <h2>Daily note reminder</h2>
                <p>Get a gentle reminder to capture your thoughts.</p>
              </div>
              <div className="reminder-controls">
                <Toggle enabled={dailyNote} onChange={() => setDailyNote(!dailyNote)} />
                <button className="time-button" type="button">9:00 AM <span>⌄</span></button>
              </div>
            </div>
          </div>

          <footer>
            <span>Changes are saved automatically</span>
            <button className="done-button" type="button">Done</button>
          </footer>
        </div>
      </section>
    </main>
  );
}

