import { useState } from 'react';
import './styles.css';

type ToggleProps = {
  checked: boolean;
  onChange: () => void;
  label: string;
  hint?: string;
};

function Toggle({ checked, onChange, label, hint }: ToggleProps) {
  return (
    <label className="toggle-row">
      <span>
        <span className="setting-label">{label}</span>
        {hint && <span className="setting-hint">{hint}</span>}
      </span>
      <button
        type="button"
        className={`toggle ${checked ? 'is-on' : ''}`}
        aria-pressed={checked}
        aria-label={label}
        onClick={onChange}
      >
        <span />
      </button>
    </label>
  );
}

export default function App() {
  const [activeSection, setActiveSection] = useState('General');
  const [theme, setTheme] = useState('System');
  const [spellcheck, setSpellcheck] = useState(true);
  const [dailyNote, setDailyNote] = useState(true);
  const [showCount, setShowCount] = useState(false);
  const [saved, setSaved] = useState(false);

  const sections = ['General', 'Editor', 'Appearance', 'Account'];

  const save = () => {
    setSaved(true);
    window.setTimeout(() => setSaved(false), 1800);
  };

  return (
    <main className="app-shell">
      <section className="settings-card" aria-label="Settings">
        <aside className="sidebar">
          <div className="brand"><span className="brand-mark">N</span><span>Notely</span></div>
          <nav aria-label="Settings sections">
            {sections.map((section) => (
              <button
                type="button"
                key={section}
                className={`nav-item ${activeSection === section ? 'active' : ''}`}
                onClick={() => setActiveSection(section)}
              >
                <span className="nav-dot" />{section}
              </button>
            ))}
          </nav>
          <button type="button" className="help-link">? <span>Help & feedback</span></button>
        </aside>

        <div className="content">
          <header className="page-heading">
            <div>
              <p className="eyebrow">Preferences</p>
              <h1>{activeSection}</h1>
              <p>Personalize how you write and organize your notes.</p>
            </div>
            <button type="button" className="close-button" aria-label="Close settings">×</button>
          </header>

          <div className="settings-stack">
            <section className="setting-section">
              <h2>Workspace</h2>
              <div className="field-grid">
                <label className="field-label">Display name<input defaultValue="Alex Morgan" /></label>
                <label className="field-label">Start page
                  <select defaultValue="All notes"><option>All notes</option><option>Daily note</option><option>Favorites</option></select>
                </label>
              </div>
            </section>

            <section className="setting-section divided">
              <h2>Writing</h2>
              <Toggle checked={spellcheck} onChange={() => setSpellcheck(!spellcheck)} label="Spell check" hint="Underline words that may need attention." />
              <Toggle checked={dailyNote} onChange={() => setDailyNote(!dailyNote)} label="Open daily note on launch" hint="Start each day with a fresh place to write." />
              <Toggle checked={showCount} onChange={() => setShowCount(!showCount)} label="Show word count" hint="Display a live count at the bottom of each note." />
            </section>

            <section className="setting-section divided">
              <h2>Appearance</h2>
              <div className="theme-options" role="radiogroup" aria-label="Color theme">
                {['Light', 'System', 'Dark'].map((option) => (
                  <button key={option} type="button" role="radio" aria-checked={theme === option} className={`theme-option ${theme === option ? 'selected' : ''}`} onClick={() => setTheme(option)}>
                    <span className={`theme-preview ${option.toLowerCase()}`}><i /></span>{option}
                  </button>
                ))}
              </div>
            </section>
          </div>

          <footer className="actions">
            <span className={saved ? 'saved visible' : 'saved'}>Changes saved</span>
            <button type="button" className="cancel-button">Cancel</button>
            <button type="button" className="save-button" onClick={save}>Save changes</button>
          </footer>
        </div>
      </section>
    </main>
  );
}

