import { useState } from "react";

type ToggleRowProps = {
  title: string;
  description: string;
  enabled: boolean;
  onChange: () => void;
};

function ToggleRow({ title, description, enabled, onChange }: ToggleRowProps) {
  return (
    <div className="setting-row">
      <div>
        <h3>{title}</h3>
        <p>{description}</p>
      </div>
      <button
        className={`toggle ${enabled ? "is-on" : ""}`}
        type="button"
        role="switch"
        aria-checked={enabled}
        aria-label={title}
        onClick={onChange}
      >
        <span />
      </button>
    </div>
  );
}

export default function App() {
  const [autosave, setAutosave] = useState(true);
  const [spellcheck, setSpellcheck] = useState(true);
  const [focusMode, setFocusMode] = useState(false);
  const [theme, setTheme] = useState("System");

  return (
    <main className="app-shell">
      <section className="settings-card" aria-labelledby="settings-title">
        <header className="card-header">
          <div className="brand-mark" aria-hidden="true">✦</div>
          <div>
            <p className="eyebrow">Papertrail</p>
            <h1 id="settings-title">Settings</h1>
          </div>
          <button className="close-button" type="button" aria-label="Close settings">×</button>
        </header>

        <nav className="tabs" aria-label="Settings sections">
          <button className="tab active" type="button">General</button>
          <button className="tab" type="button">Editor</button>
          <button className="tab" type="button">Account</button>
        </nav>

        <div className="settings-content">
          <section aria-labelledby="appearance-heading">
            <h2 id="appearance-heading">Appearance</h2>
            <label className="select-row">
              <span>
                <strong>Theme</strong>
                <small>Choose how Papertrail looks.</small>
              </span>
              <select value={theme} onChange={(event) => setTheme(event.target.value)}>
                <option>System</option>
                <option>Light</option>
                <option>Dark</option>
              </select>
            </label>
          </section>

          <section aria-labelledby="writing-heading">
            <h2 id="writing-heading">Writing</h2>
            <ToggleRow
              title="Autosave"
              description="Save changes as you write."
              enabled={autosave}
              onChange={() => setAutosave(!autosave)}
            />
            <ToggleRow
              title="Spellcheck"
              description="Highlight potential spelling mistakes."
              enabled={spellcheck}
              onChange={() => setSpellcheck(!spellcheck)}
            />
            <ToggleRow
              title="Focus mode"
              description="Hide navigation while editing a note."
              enabled={focusMode}
              onChange={() => setFocusMode(!focusMode)}
            />
          </section>
        </div>

        <footer className="card-footer">
          <span>Changes are saved automatically.</span>
          <button className="done-button" type="button">Done</button>
        </footer>
      </section>
    </main>
  );
}

