import { useState } from "react";
import "./styles.css";

type ToggleProps = {
  checked: boolean;
  onChange: () => void;
  label: string;
  detail: string;
};

function Toggle({ checked, onChange, label, detail }: ToggleProps) {
  return (
    <label className="setting-row">
      <span>
        <span className="setting-label">{label}</span>
        <span className="setting-detail">{detail}</span>
      </span>
      <input
        aria-label={label}
        checked={checked}
        className="toggle-input"
        onChange={onChange}
        type="checkbox"
      />
      <span className="toggle" aria-hidden="true"><span /></span>
    </label>
  );
}

export default function App() {
  const [theme, setTheme] = useState("System");
  const [font, setFont] = useState("Sans");
  const [focusMode, setFocusMode] = useState(true);
  const [reminders, setReminders] = useState(false);

  return (
    <main className="page-shell">
      <section className="settings-card" aria-labelledby="settings-title">
        <header className="card-header">
          <div className="mark" aria-hidden="true">N</div>
          <div>
            <p className="eyebrow">Papertrail</p>
            <h1 id="settings-title">Settings</h1>
          </div>
          <button className="close-button" aria-label="Close settings">×</button>
        </header>

        <nav className="tabs" aria-label="Settings sections">
          <button className="tab active">Appearance</button>
          <button className="tab">Editor</button>
          <button className="tab">Account</button>
        </nav>

        <div className="settings-content">
          <section className="setting-group" aria-labelledby="display-heading">
            <div className="group-heading">
              <h2 id="display-heading">Display</h2>
              <p>Make your writing space feel like yours.</p>
            </div>

            <div className="choice-block">
              <span className="choice-label">Theme</span>
              <div className="segmented" role="group" aria-label="Theme">
                {["Light", "System", "Dark"].map((option) => (
                  <button
                    className={theme === option ? "selected" : ""}
                    key={option}
                    onClick={() => setTheme(option)}
                  >
                    {option}
                  </button>
                ))}
              </div>
            </div>

            <div className="select-row">
              <div>
                <span className="choice-label">Note font</span>
                <span className="setting-detail">Used for new and existing notes</span>
              </div>
              <label className="select-wrap">
                <span className="sr-only">Note font</span>
                <select value={font} onChange={(event) => setFont(event.target.value)}>
                  <option>Sans</option>
                  <option>Serif</option>
                  <option>Mono</option>
                </select>
              </label>
            </div>
          </section>

          <section className="setting-group preferences" aria-labelledby="preferences-heading">
            <div className="group-heading">
              <h2 id="preferences-heading">Writing preferences</h2>
            </div>
            <Toggle
              checked={focusMode}
              detail="Hide navigation while you write"
              label="Focus mode"
              onChange={() => setFocusMode(!focusMode)}
            />
            <Toggle
              checked={reminders}
              detail="A gentle nudge for unfinished notes"
              label="Daily reminder"
              onChange={() => setReminders(!reminders)}
            />
          </section>
        </div>

        <footer className="card-footer">
          <span>Changes are saved automatically</span>
          <button className="done-button">Done</button>
        </footer>
      </section>
    </main>
  );
}

