import { useState } from "react";
import "./styles.css";

type ToggleProps = {
  enabled: boolean;
  onChange: () => void;
  label: string;
};

function Toggle({ enabled, onChange, label }: ToggleProps) {
  return (
    <button
      aria-label={label}
      aria-pressed={enabled}
      className={`toggle ${enabled ? "is-on" : ""}`}
      onClick={onChange}
      type="button"
    >
      <span />
    </button>
  );
}

export default function App() {
  const [activeNav, setActiveNav] = useState("General");
  const [appearance, setAppearance] = useState("System");
  const [font, setFont] = useState("Inter");
  const [compact, setCompact] = useState(false);
  const [spellcheck, setSpellcheck] = useState(true);
  const [links, setLinks] = useState(true);
  const [saved, setSaved] = useState(false);

  const nav = [
    ["⌘", "General"],
    ["✦", "Appearance"],
    ["⌕", "Editor"],
    ["◌", "Sync"],
    ["♧", "Shortcuts"],
  ];

  const save = () => {
    setSaved(true);
    window.setTimeout(() => setSaved(false), 1800);
  };

  return (
    <main className="app-shell">
      <section className="settings-card" aria-label="Settings">
        <aside className="sidebar">
          <div className="brand">
            <div className="brand-mark">n</div>
            <div>
              <strong>Noted</strong>
              <span>Personal workspace</span>
            </div>
          </div>

          <nav aria-label="Settings sections">
            {nav.map(([icon, item]) => (
              <button
                className={`nav-item ${activeNav === item ? "active" : ""}`}
                key={item}
                onClick={() => setActiveNav(item)}
                type="button"
              >
                <span className="nav-icon">{icon}</span>
                {item}
              </button>
            ))}
          </nav>

          <div className="sidebar-bottom">
            <div className="storage-label"><span>Storage</span><span>62%</span></div>
            <div className="storage-bar"><span /></div>
            <p>3.1 GB of 5 GB used</p>
            <button className="upgrade" type="button">Upgrade plan <span>↗</span></button>
            <button className="profile" type="button">
              <span className="avatar">AR</span>
              <span><strong>Alex Rivera</strong><small>Free plan</small></span>
              <b>⌄</b>
            </button>
          </div>
        </aside>

        <div className="content">
          <header>
            <div>
              <p className="eyebrow">Preferences</p>
              <h1>{activeNav}</h1>
              <p className="subtitle">Personalize the way your workspace feels and works.</p>
            </div>
            <button className="close" aria-label="Close settings" type="button">×</button>
          </header>

          <div className="settings-list">
            <section className="setting-section">
              <div className="section-heading"><h2>Interface</h2><p>Choose a look that works for you.</p></div>
              <div className="setting-row appearance-row">
                <div><h3>Appearance</h3><p>Set your preferred color mode.</p></div>
                <div className="segmented" role="group" aria-label="Appearance">
                  {[["☀", "Light"], ["◐", "System"], ["☾", "Dark"]].map(([icon, mode]) => (
                    <button className={appearance === mode ? "selected" : ""} key={mode} onClick={() => setAppearance(mode)} type="button"><span>{icon}</span>{mode}</button>
                  ))}
                </div>
              </div>
              <div className="setting-row">
                <div><h3>Sidebar density</h3><p>Make space for more notes in your sidebar.</p></div>
                <Toggle enabled={compact} label="Toggle compact sidebar" onChange={() => setCompact(!compact)} />
              </div>
            </section>

            <section className="setting-section">
              <div className="section-heading"><h2>Writing</h2><p>Fine-tune your note editing experience.</p></div>
              <div className="setting-row">
                <div><h3>Editor font</h3><p>Used when composing and reading notes.</p></div>
                <label className="select-wrap"><select value={font} onChange={(event) => setFont(event.target.value)}><option>Inter</option><option>Georgia</option><option>Mono</option></select></label>
              </div>
              <div className="setting-row">
                <div><h3>Spell check</h3><p>Underline potential spelling mistakes as you type.</p></div>
                <Toggle enabled={spellcheck} label="Toggle spell check" onChange={() => setSpellcheck(!spellcheck)} />
              </div>
              <div className="setting-row">
                <div><h3>Link suggestions</h3><p>Suggest related notes while writing.</p></div>
                <Toggle enabled={links} label="Toggle link suggestions" onChange={() => setLinks(!links)} />
              </div>
            </section>
          </div>

          <footer>
            <span>{saved ? "Changes saved" : "Changes are saved automatically"}</span>
            <button className="save-button" onClick={save} type="button">{saved ? "Saved ✓" : "Save changes"}</button>
          </footer>
        </div>
      </section>
    </main>
  );
}

