import { useState, type ReactNode } from 'react';
import './styles.css';

type IconName = 'profile' | 'palette' | 'editor' | 'bell' | 'shield';

const Icon = ({ name, size = 20 }: { name: IconName; size?: number }) => {
  const paths: Record<IconName, ReactNode> = {
    profile: <><circle cx="12" cy="8" r="3.5" /><path d="M5.5 20c.7-3.2 3-5 6.5-5s5.8 1.8 6.5 5" /></>,
    palette: <><path d="M12 3C6.5 3 3 6.7 3 11.4 3 15.3 5.7 18 9.3 18h1.1c.9 0 1.4-.8 1-1.6-.3-.7.2-1.4 1-1.4h1.4c4 0 7.2-2.6 7.2-6.1C21 5.5 17.2 3 12 3Z" /><circle cx="7.5" cy="11" r=".8" fill="currentColor" /><circle cx="10" cy="7.5" r=".8" fill="currentColor" /><circle cx="14" cy="7" r=".8" fill="currentColor" /></>,
    editor: <><path d="M6 4.5h9.5M6 9h12M6 13.5h8M6 18h10" /><path d="M17 16.5 20.5 13l1.5 1.5-3.5 3.5-2.5.8.8-2.8Z" /></>,
    bell: <><path d="M18 10a6 6 0 0 0-12 0c0 7-3 7-3 8.5h18C21 17 18 17 18 10Z" /><path d="M10 21h4" /></>,
    shield: <path d="M12 3.5 19 6v5.2c0 4.4-2.9 7.7-7 9.3-4.1-1.6-7-4.9-7-9.3V6l7-2.5Z" />,
  };
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>;
};

const nav = [
  ['My account', 'profile'], ['Appearance', 'palette'], ['Editor', 'editor'], ['Notifications', 'bell'], ['Privacy', 'shield'],
] as [string, IconName][];

export default function App() {
  const [active, setActive] = useState('Appearance');
  const [theme, setTheme] = useState('System');
  const [font, setFont] = useState('Inter');
  const [width, setWidth] = useState('Comfortable');
  const [serif, setSerif] = useState(false);
  const [lineNumbers, setLineNumbers] = useState(true);

  return (
    <main className="app-shell">
      <section className="settings-card" aria-label="Settings">
        <aside className="sidebar">
          <div className="brand"><span className="brand-mark">N</span><span>noto</span></div>
          <p className="eyebrow">SETTINGS</p>
          <nav>{nav.map(([label, icon]) => <button key={label} className={active === label ? 'nav-item active' : 'nav-item'} onClick={() => setActive(label)}><Icon name={icon} /><span>{label}</span></button>)}</nav>
          <div className="sidebar-footer"><div className="avatar">SM</div><div><strong>Sarah Miller</strong><span>Personal space</span></div><button className="more" aria-label="More options">•••</button></div>
        </aside>
        <div className="content">
          <header><div><p className="eyebrow">PREFERENCES</p><h1>Appearance</h1><p className="subtitle">Make noto feel like your own.</p></div><button className="close" aria-label="Close settings">×</button></header>
          <div className="content-body">
            <section className="setting-section"><div className="section-heading"><h2>Theme</h2><p>Choose how noto looks to you.</p></div><div className="theme-grid">{['Light', 'Dark', 'System'].map(option => <button key={option} className={theme === option ? 'theme-option selected' : 'theme-option'} onClick={() => setTheme(option)}><span className={'theme-preview ' + option.toLowerCase()}><i /><b /></span><span>{option}</span>{theme === option && <em>✓</em>}</button>)}</div></section>
            <section className="setting-section compact"><div className="section-heading"><h2>Editor</h2><p>Fine-tune your writing space.</p></div><div className="form-row"><label htmlFor="font">Font</label><select id="font" value={font} onChange={e => setFont(e.target.value)}><option>Inter</option><option>Source Sans 3</option><option>IBM Plex Sans</option></select></div><div className="form-row"><label htmlFor="width">Content width</label><select id="width" value={width} onChange={e => setWidth(e.target.value)}><option>Comfortable</option><option>Compact</option><option>Wide</option></select></div><Toggle label="Use serif headings" description="Give note titles a classic feel." checked={serif} onChange={setSerif} /><Toggle label="Show line numbers" description="Display line numbers in code blocks." checked={lineNumbers} onChange={setLineNumbers} /></section>
          </div>
          <footer><span>Changes are saved automatically</span><button className="done">Done</button></footer>
        </div>
      </section>
    </main>
  );
}

function Toggle({ label, description, checked, onChange }: { label: string; description: string; checked: boolean; onChange: (value: boolean) => void }) {
  return <div className="toggle-row"><div><strong>{label}</strong><p>{description}</p></div><button className={checked ? 'switch on' : 'switch'} onClick={() => onChange(!checked)} aria-pressed={checked}><span /></button></div>;
}

