import { useState } from "react";
import "./styles.css";

type ToggleProps = {
  checked: boolean;
  onChange: () => void;
  label: string;
  description?: string;
};

function Toggle({ checked, onChange, label, description }: ToggleProps) {
  return (
    <label className="toggle-row">
      <span>
        <strong>{label}</strong>
        {description && <small>{description}</small>}
      </span>
      <input type="checkbox" checked={checked} onChange={onChange} />
      <span className="switch" aria-hidden="true" />
    </label>
  );
}

export default function App() {
  const [theme, setTheme] = useState("System");
  const [autosave, setAutosave] = useState(true);
  const [spellcheck, setSpellcheck] = useState(true);
  const [focusMode, setFocusMode] = useState(false);
  const [fontSize, setFontSize] = useState(16);

  return (
    <main className="app-shell">
      <section className="settings-card" aria-labelledby="settings-title">
        <aside className="sidebar">
          <div className="brand"><span className="brand-mark">✦</span> Notely</div>
          <nav aria-label="Settings navigation">
            <a className="nav-item active" href="#general"><span>◈</span> General</a>
            <a className="nav-item" href="#editor"><span>⌁</span> Editor</a>
            <a className="nav-item" href="#appearance"><span>◐</span> Appearance</a>
            <a className="nav-item" href="#shortcuts"><span>⌘</span> Shortcuts</a>
          </nav>
          <div className="account">
            <div className="avatar">AM</div>
            <div><strong>Alex Morgan</strong><small>Personal workspace</small></div>
            <span className="more">•••</span>
          </div>
        </aside>

        <div className="content">
          <header>
            <div>
              <p className="eyebrow">PREFERENCES</p>
              <h1 id="settings-title">General settings</h1>
              <p className="intro">Make your workspace feel like home.</p>
            </div>
            <button className="close" aria-label="Close settings">×</button>
          </header>

          <div className="settings-list">
            <section className="setting-section" id="appearance">
              <h2>Appearance</h2>
              <div className="setting-line theme-line">
                <div><strong>Color theme</strong><small>Choose how Notely looks for you</small></div>
                <div className="segmented" role="group" aria-label="Color theme">
                  {["Light", "System", "Dark"].map((option) => (
                    <button key={option} onClick={() => setTheme(option)} className={theme === option ? "selected" : ""}>{option}</button>
                  ))}
                </div>
              </div>
              <div className="setting-line font-line">
                <div><strong>Editor font size</strong><small>Set a comfortable reading size</small></div>
                <div className="font-control">
                  <button onClick={() => setFontSize(Math.max(12, fontSize - 1))} aria-label="Decrease font size">−</button>
                  <span>{fontSize} px</span>
                  <button onClick={() => setFontSize(Math.min(24, fontSize + 1))} aria-label="Increase font size">+</button>
                </div>
              </div>
            </section>

            <section className="setting-section" id="editor">
              <h2>Writing</h2>
              <Toggle checked={autosave} onChange={() => setAutosave(!autosave)} label="Save changes automatically" description="Your notes are saved as you write" />
              <Toggle checked={spellcheck} onChange={() => setSpellcheck(!spellcheck)} label="Check spelling" description="Highlight possible spelling mistakes" />
              <Toggle checked={focusMode} onChange={() => setFocusMode(!focusMode)} label="Focus mode" description="Hide navigation while you are writing" />
            </section>
          </div>

          <footer>
            <p>Changes are saved automatically</p>
            <button className="done">Done</button>
          </footer>
        </div>
      </section>
    </main>
  );
}

