import { useState } from 'react';
import './styles.css';

type SwitchProps = {
  checked: boolean;
  onChange: () => void;
  label: string;
  description?: string;
};

function Switch({ checked, onChange, label, description }: SwitchProps) {
  return (
    <div className="setting-row">
      <div>
        <div className="setting-label">{label}</div>
        {description && <div className="setting-description">{description}</div>}
      </div>
      <button
        type="button"
        className={`switch ${checked ? 'is-on' : ''}`}
        onClick={onChange}
        aria-pressed={checked}
        aria-label={label}
      >
        <span />
      </button>
    </div>
  );
}

export default function App() {
  const [sidebar, setSidebar] = useState(true);
  const [spellcheck, setSpellcheck] = useState(true);
  const [focusMode, setFocusMode] = useState(false);
  const [font, setFont] = useState('Inter');

  return (
    <main className="app-shell">
      <section className="panel" aria-label="Settings">
        <header className="panel-header">
          <div className="eyebrow">Papertrail</div>
          <h1>Settings</h1>
          <p>Shape your writing space around the way you think.</p>
        </header>

        <nav className="tabs" aria-label="Settings categories">
          <button className="tab active" type="button">General</button>
          <button className="tab" type="button">Editor</button>
          <button className="tab" type="button">Account</button>
        </nav>

        <div className="settings-content">
          <section className="settings-group" aria-labelledby="workspace-heading">
            <h2 id="workspace-heading">Workspace</h2>
            <Switch
              label="Show sidebar"
              description="Keep your notebooks one click away."
              checked={sidebar}
              onChange={() => setSidebar(!sidebar)}
            />
            <div className="setting-row compact">
              <div>
                <div className="setting-label">Start page</div>
                <div className="setting-description">Choose what opens when you arrive.</div>
              </div>
              <select defaultValue="Last note" aria-label="Start page">
                <option>Last note</option>
                <option>All notes</option>
                <option>Daily note</option>
              </select>
            </div>
          </section>

          <section className="settings-group" aria-labelledby="writing-heading">
            <h2 id="writing-heading">Writing</h2>
            <div className="setting-row compact">
              <div>
                <div className="setting-label">Typeface</div>
                <div className="setting-description">A comfortable face for longer thoughts.</div>
              </div>
              <div className="segmented" role="group" aria-label="Typeface">
                {['Inter', 'Serif', 'Mono'].map((option) => (
                  <button
                    key={option}
                    type="button"
                    className={font === option ? 'selected' : ''}
                    onClick={() => setFont(option)}
                  >
                    {option}
                  </button>
                ))}
              </div>
            </div>
            <Switch
              label="Spell check"
              description="Gently flag words that may need a second look."
              checked={spellcheck}
              onChange={() => setSpellcheck(!spellcheck)}
            />
            <Switch
              label="Focus mode"
              description="Fade interface details while you write."
              checked={focusMode}
              onChange={() => setFocusMode(!focusMode)}
            />
          </section>
        </div>

        <footer className="panel-footer">
          <span>Changes save automatically</span>
          <button className="sign-out" type="button">Sign out</button>
        </footer>
      </section>
    </main>
  );
}

