          <div className="section-heading">
            <h2>Writing</h2>
            <p>Defaults for every new note.</p>
          </div>
          <label className="setting-row select-row">
            <span>
              <span className="setting-label">Default note format</span>
              <span className="setting-detail">Choose how new notes begin.</span>
            </span>
            <select defaultValue="Markdown" aria-label="Default note format">
              <option>Markdown</option>
              <option>Plain text</option>
              <option>Rich text</option>
            </select>
          </label>
          <Toggle checked={spellcheck} onChange={() => setSpellcheck(!spellcheck)} label="Spell check" detail="Underline possible spelling mistakes." />
        </div>

        <div className="section">
          <div className="section-heading">
            <h2>Notes</h2>
            <p>Keep your work in sync and easy to scan.</p>
          </div>
          <Toggle checked={autoSave} onChange={() => setAutoSave(!autoSave)} label="Save changes automatically" detail="Updates are saved while you write." />
          <Toggle checked={compact} onChange={() => setCompact(!compact)} label="Compact note list" detail="Show more notes in the sidebar." />
        </div>

        <footer className="card-footer">
          <span className="status" aria-live="polite">{saved ? "Changes saved" : "All changes are local"}</span>
          <button className="save-button" type="button" onClick={save}>{saved ? "Saved" : "Save changes"}</button>
        </footer>
      </section>
    </main>
  );
}

