import { useState } from "react";
import "./styles.css";

type ToggleProps = {
  checked: boolean;
  onChange: () => void;
  label: string;
  description: string;
};

function Toggle({ checked, onChange, label, description }: ToggleProps) {
  return (
    <label className="setting-row">
      <span>
        <span className="setting-label">{label}</span>
        <span className="setting-description">{description}</span>
      </span>
      <input
        className="toggle-input"
        type="checkbox"
        checked={checked}
        onChange={onChange}
        aria-label={label}
      />
      <span className="toggle" aria-hidden="true"><span /></span>
    </label>
  );
}

export default function App() {
  const [accent, setAccent] = useState("violet");
  const [lineNumbers, setLineNumbers] = useState(false);
  const [spellcheck, setSpellcheck] = useState(true);
  const [links, setLinks] = useState(true);

  return (
    <main className="page-shell">
      <section className="settings-panel" aria-labelledby="settings-title">
        <header className="panel-header">
          <div className="app-mark">N</div>
          <div>
            <p className="eyebrow">Papertrail</p>
            <h1 id="settings-title">Settings</h1>
          </div>
          <button className="close-button" aria-label="Close settings">×</button>
        </header>

        <nav className="tabs" aria-label="Settings sections">
          <button className="active">Appearance</button>
          <button>Editor</button>
          <button>Account</button>
        </nav>

        <div className="settings-content">
          <section>
            <div className="section-heading">
              <h2>Theme</h2>
              <p>Personalize the way your workspace looks.</p>
            </div>
            <div className="theme-grid">
              <button className="theme-option selected">
                <span className="theme-preview light-preview"><i /><b /></span>
                <span>Light</span><em>Selected</em>
              </button>
              <button className="theme-option">
                <span className="theme-preview dark-preview"><i /><b /></span>
                <span>Dark</span>
              </button>
              <button className="theme-option">
                <span className="theme-preview system-preview"><i /><b /></span>
                <span>System</span>
              </button>
            </div>
          </section>

          <section className="section-divider">
            <div className="section-heading inline-heading">
              <div><h2>Accent color</h2><p>Used for links, selections, and controls.</p></div>
            </div>
            <div className="color-picker" aria-label="Accent color">
              {[
                ["violet", "#7c6cff"], ["blue", "#4e9cf5"], ["rose", "#ec7188"],
                ["orange", "#ed9c58"], ["green", "#57b68c"]
              ].map(([name, color]) => (
                <button key={name} className={`color-dot ${accent === name ? "chosen" : ""}`} style={{ backgroundColor: color }} onClick={() => setAccent(name)} aria-label={`${name} accent`} />
              ))}
            </div>
          </section>

          <section className="section-divider editor-options">
            <div className="section-heading"><h2>Writing</h2><p>Fine-tune your editor experience.</p></div>
            <Toggle label="Spell check" description="Highlight possible spelling mistakes." checked={spellcheck} onChange={() => setSpellcheck(!spellcheck)} />
            <Toggle label="Automatic links" description="Turn pasted URLs into clickable links." checked={links} onChange={() => setLinks(!links)} />
            <Toggle label="Line numbers" description="Show line numbers in focused mode." checked={lineNumbers} onChange={() => setLineNumbers(!lineNumbers)} />
          </section>
        </div>

        <footer className="panel-footer">
          <span>Changes are saved automatically</span>
          <button className="done-button">Done</button>
        </footer>
      </section>
    </main>
  );
}

