import { useState } from 'react';
import './styles.css';

type ToggleProps = {
  checked: boolean;
  onChange: () => void;
  label: string;
  description: string;
};

function Toggle({ checked, onChange, label, description }: ToggleProps) {
  return (
    <div className="preference-row">
      <div>
        <p className="preference-label">{label}</p>
        <p className="preference-description">{description}</p>
      </div>
      <button
        type="button"
        className={`toggle ${checked ? 'is-on' : ''}`}
        onClick={onChange}
        aria-pressed={checked}
        aria-label={label}
      >
        <span />
      </button>
    </div>
  );
}

export default function App() {
  const [theme, setTheme] = useState<'light' | 'dark' | 'system'>('system');
  const [autosave, setAutosave] = useState(true);
  const [spellcheck, setSpellcheck] = useState(true);
  const [compact, setCompact] = useState(false);

  return (
    <main className="app-shell">
      <section className="settings-card" aria-label="Settings">
        <header className="settings-header">
          <div className="app-mark" aria-hidden="true"><span>n</span></div>
          <div>
            <p className="eyebrow">Notebook</p>
            <h1>Settings</h1>
          </div>
          <button className="close-button" type="button" aria-label="Close settings">×</button>
        </header>

        <nav className="settings-nav" aria-label="Settings categories">
          <button className="nav-item active" type="button"><span>◈</span> General</button>
          <button className="nav-item" type="button"><span>⌘</span> Editor</button>
          <button className="nav-item" type="button"><span>◌</span> Account</button>
        </nav>

        <div className="settings-content">
          <section className="settings-section">
            <div className="section-heading">
              <h2>Appearance</h2>
              <p>Choose how Notebook looks on this device.</p>
            </div>
            <div className="theme-picker" role="radiogroup" aria-label="Theme">
              {(['light', 'dark', 'system'] as const).map((option) => (
                <button
                  key={option}
                  type="button"
                  role="radio"
                  aria-checked={theme === option}
                  className={`theme-option ${theme === option ? 'selected' : ''}`}
                  onClick={() => setTheme(option)}
                >
                  <span className={`theme-preview ${option}`} aria-hidden="true"><i /><b /></span>
                  <span>{option[0].toUpperCase() + option.slice(1)}</span>
                </button>
              ))}
            </div>
          </section>

          <section className="settings-section preferences">
            <div className="section-heading">
              <h2>Writing</h2>
              <p>Set up your everyday editing experience.</p>
            </div>
            <Toggle checked={autosave} onChange={() => setAutosave(!autosave)} label="Save notes automatically" description="Keep changes safe as you write." />
            <Toggle checked={spellcheck} onChange={() => setSpellcheck(!spellcheck)} label="Check spelling" description="Underline possible spelling mistakes." />
            <Toggle checked={compact} onChange={() => setCompact(!compact)} label="Compact note list" description="Show more notes in the sidebar." />
          </section>
        </div>

        <footer className="settings-footer">
          <span>Changes are saved automatically</span>
          <button type="button" className="done-button">Done</button>
        </footer>
      </section>
    </main>
  );
}

