  const [links, setLinks] = useState(false);

  return (
    <main className="app-shell">
      <section className="settings-card" aria-label="Settings">
        <aside className="sidebar">
          <div className="brand"><span className="brand-mark">N</span><span>Notebook</span></div>
          <nav aria-label="Settings sections">
            <button className="nav-item active"><span className="nav-icon">⌘</span>General</button>
            <button className="nav-item"><span className="nav-icon">A</span>Editor</button>
            <button className="nav-item"><span className="nav-icon">⌕</span>Search</button>
            <button className="nav-item"><span className="nav-icon">♧</span>Appearance</button>
          </nav>
          <div className="sidebar-footer"><span className="avatar">ME</span><span>My workspace</span><span className="chevron">⌄</span></div>
        </aside>

        <div className="content">
          <header className="page-header">
            <div><p className="eyebrow">PREFERENCES</p><h1>General settings</h1><p className="subtitle">Make Notebook feel right for you.</p></div>
            <button className="close-button" aria-label="Close settings">×</button>
          </header>

          <div className="settings-section">
            <h2>Appearance</h2>
            <div className="theme-grid" role="radiogroup" aria-label="Theme">
              {['Light', 'System', 'Dark'].map((option) => (
                <button key={option} className={`theme-option ${theme === option ? 'selected' : ''}`} onClick={() => setTheme(option)} role="radio" aria-checked={theme === option}>
                  <span className={`theme-preview ${option.toLowerCase()}`}><i /><b /></span>
                  <span>{option}</span>
                  {theme === option && <span className="selected-dot">✓</span>}
                </button>
              ))}
            </div>
          </div>

          <div className="settings-section editor-section">
            <h2>Editor</h2>
            <div className="control-row">
              <div><span className="setting-label">Default font size</span><span className="setting-description">Used when creating new notes.</span></div>
              <div className="stepper">
                <button onClick={() => setFontSize((size) => Math.max(12, size - 1))} aria-label="Decrease font size">−</button>
                <output>{fontSize} px</output>
                <button onClick={() => setFontSize((size) => Math.min(24, size + 1))} aria-label="Increase font size">+</button>
              </div>
            </div>
            <Toggle label="Save changes automatically" description="Your notes are saved as you type." checked={autosave} onChange={() => setAutosave(!autosave)} />
            <Toggle label="Check spelling while typing" description="Highlight words that may need attention." checked={spellcheck} onChange={() => setSpellcheck(!spellcheck)} />
            <Toggle label="Recognize links automatically" description="Turn pasted URLs into clickable links." checked={links} onChange={() => setLinks(!links)} />
          </div>

          <footer className="content-footer"><span>Changes are saved automatically</span><button className="done-button">Done</button></footer>
        </div>
      </section>
    </main>
  );
}

