import { useState } from "react";
import "./styles.css";

type ToggleProps = {
  checked: boolean;
  label: string;
  onChange: () => void;
};

function Toggle({ checked, label, onChange }: ToggleProps) {
  return (
    <button
      className={`toggle ${checked ? "is-on" : ""}`}
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      onClick={onChange}
    >
      <span />
    </button>
  );
}

export default function App() {
  const [theme, setTheme] = useState("System");
  const [font, setFont] = useState("Inter");
  const [fontSize, setFontSize] = useState(16);
  const [spellcheck, setSpellcheck] = useState(true);
  const [linkPreview, setLinkPreview] = useState(true);
  const [dailyNote, setDailyNote] = useState(false);

  return (
    <main className="app-shell">
      <section className="settings" aria-labelledby="settings-title">
        <header className="settings-header">
          <div>
            <p className="eyebrow">Workspace</p>
            <h1 id="settings-title">Settings</h1>
            <p className="subtitle">Make the space yours.</p>
          </div>
          <button className="close-button" type="button" aria-label="Close settings">×</button>
        </header>

        <nav className="tabs" aria-label="Settings sections">
          <button className="tab active" type="button">General</button>
          <button className="tab" type="button">Editor</button>
          <button className="tab" type="button">Account</button>
        </nav>

        <div className="settings-body">
          <section className="group" aria-labelledby="appearance-heading">
            <h2 id="appearance-heading">Appearance</h2>
            <div className="field-row">
              <div><label htmlFor="theme">Theme</label><p>Choose how your notes look.</p></div>
              <div className="select-wrap"><select id="theme" value={theme} onChange={(event) => setTheme(event.target.value)}><option>System</option><option>Light</option><option>Dark</option></select></div>
            </div>
            <div className="field-row">
              <div><label htmlFor="font">Interface font</label><p>Used throughout the application.</p></div>
              <div className="select-wrap"><select id="font" value={font} onChange={(event) => setFont(event.target.value)}><option>Inter</option><option>DM Sans</option><option>Source Sans 3</option></select></div>
            </div>
          </section>

          <section className="group" aria-labelledby="editor-heading">
            <h2 id="editor-heading">Editor</h2>
            <div className="field-row range-row">
              <div><label htmlFor="font-size">Text size</label><p>Set a comfortable reading size.</p></div>
              <div className="range-control"><input id="font-size" type="range" min="12" max="22" value={fontSize} onChange={(event) => setFontSize(Number(event.target.value))} /><output>{fontSize}px</output></div>
            </div>
            <div className="switch-row"><div><label>Spell check</label><p>Highlight possible spelling mistakes.</p></div><Toggle label="Toggle spell check" checked={spellcheck} onChange={() => setSpellcheck(!spellcheck)} /></div>
            <div className="switch-row"><div><label>Link previews</label><p>Show a preview when pasting a web link.</p></div><Toggle label="Toggle link previews" checked={linkPreview} onChange={() => setLinkPreview(!linkPreview)} /></div>
            <div className="switch-row"><div><label>Open daily note on launch</label><p>Start each day with a blank page.</p></div><Toggle label="Toggle daily note" checked={dailyNote} onChange={() => setDailyNote(!dailyNote)} /></div>
          </section>
        </div>

        <footer className="settings-footer"><button className="cancel" type="button">Cancel</button><button className="save" type="button">Save changes</button></footer>
      </section>
    </main>
  );
}

