              <select id="theme" value={theme} onChange={(event) => setTheme(event.target.value)}>
                <option>System</option><option>Light</option><option>Dark</option>
              </select>
            </div>
            <div className="control-row">
              <div><label htmlFor="font">Editor font</label><p>Used while you write notes.</p></div>
              <select id="font" value={font} onChange={(event) => setFont(event.target.value)}>
