import { useState } from "react";
import "./styles.css";

type ToggleProps = {
  checked: boolean;
  label: string;
  onChange: () => void;
};

function Toggle({ checked, label, onChange }: ToggleProps) {
  return (
    <button
      aria-checked={checked}
      aria-label={label}
      className={`toggle ${checked ? "is-on" : ""}`}
      onClick={onChange}
      role="switch"
      type="button"
    >
      <span className="toggle-knob" />
    </button>
  );
}

export default function App() {
  const [sync, setSync] = useState(true);
  const [spellcheck, setSpellcheck] = useState(true);
  const [compact, setCompact] = useState(false);
  const [saved, setSaved] = useState(false);

  const save = () => {
    setSaved(true);
    window.setTimeout(() => setSaved(false), 1800);
  };

  return (
    <main className="page-shell">
      <section className="settings-card" aria-labelledby="settings-title">
        <header className="card-header">
          <div className="app-mark" aria-hidden="true"><span /></div>
          <div>
            <p className="eyebrow">Paperlane</p>
            <h1 id="settings-title">Settings</h1>
          </div>
          <button className="close-button" type="button" aria-label="Close settings">×</button>
        </header>

        <nav className="tabs" aria-label="Settings sections">
          <button className="tab is-active" type="button">General</button>
          <button className="tab" type="button">Editor</button>
          <button className="tab" type="button">Account</button>
        </nav>

        <div className="settings-content">
          <section className="setting-group" aria-labelledby="workspace-heading">
            <h2 id="workspace-heading">Workspace</h2>
            <label className="field-label" htmlFor="workspace-name">Workspace name</label>
            <input id="workspace-name" className="text-input" defaultValue="My notes" />
            <p className="field-help">Shown at the top of your sidebar.</p>
          </section>

          <section className="setting-group preferences" aria-labelledby="preferences-heading">
            <h2 id="preferences-heading">Preferences</h2>
            <div className="setting-row">
              <div><h3>Cloud sync</h3><p>Keep your notes available across devices.</p></div>
              <Toggle checked={sync} label="Toggle cloud sync" onChange={() => setSync(!sync)} />
            </div>
            <div className="setting-row">
              <div><h3>Spell check</h3><p>Underline possible spelling mistakes while typing.</p></div>
              <Toggle checked={spellcheck} label="Toggle spell check" onChange={() => setSpellcheck(!spellcheck)} />
            </div>
            <div className="setting-row">
              <div><h3>Compact sidebar</h3><p>Use a denser layout for your notebook list.</p></div>
              <Toggle checked={compact} label="Toggle compact sidebar" onChange={() => setCompact(!compact)} />
            </div>
          </section>
        </div>

        <footer className="card-footer">
          <button className="cancel-button" type="button">Cancel</button>
          <button className="save-button" type="button" onClick={save}>{saved ? "Saved" : "Save changes"}</button>
        </footer>
      </section>
    </main>
  );
}

